    else if(s==='books'){const book=add(new THREE.Mesh(new THREE.BoxGeometry(.9,1.3,.24),new THREE.MeshStandardMaterial({color:0x5c160f,roughness:.82})));book.position.y=.65;book.rotation.z=-.16;const spine=add(new THREE.Mesh(new THREE.BoxGeometry(.12,1.34,.28),mats.gold));spine.position.set(-.43,.65,0);spine.rotation.z=-.16}
